from pathlib import Path
from collections import Counter
import json,re
H=Path(__file__).resolve().parent
es=json.loads((H/'entries.json').read_text())
receipts=[]
for p in sorted(H.glob('root*.json')):
    for i,r in enumerate(json.loads(p.read_text())):receipts.append({'receipt_id':f'{p.name} record {i}','source_file':p.name,'raw':r})
(H/'receipts.json').write_text(json.dumps({'month':'2025-09','receipts':receipts,'capability_errors':'child_errors.json','note':'Complete root query/result objects are preserved. Child access errors are not evidence of absent history.'},ensure_ascii=False,indent=2)+'\n')
wc={e['id']:len(' '.join([e['summary'],*e['definitions'],*e['result'].values(),*e['example'].values(),e['limits'],e['extension']]).split()) for e in es}
for e in es:
    o=e['original'];assert o['evidence']+'@'+o['date'] in o['source_excerpt'];assert o['original_question'] is None
report={'month':'2025-09','entries':len(es),'entry_ids':[e['id'] for e in es],'evidence_counts':dict(Counter(e['original']['evidence'] for e in es)),'recovered_dates':sorted({e['original']['date'] for e in es}),'substantive_words':sum(wc.values()),'substantive_word_counts':wc,'raw_successful_receipts':len(receipts),'historical_attribution':'Source excerpts are literal returned retrieval lines with matching U/A roles. They remain retrieval summaries rather than asserted verbatim prompts. All revised questions and proofs are newly authored.','coverage':'Contraction composition/residuals; cosine fixed-point tails; free-group cocycles and sharp weighted bounds; cokernel torsion; trace induction; genuine11a1 counts and Hecke recurrence; correct Sym2 local factors; Fourier aliasing; contour multiplicity; p-adic mu/lambda; cross-ratio moduli pushforward; Legendre certificates; fractional ownership; bisimulation; square-root smoothing and micro rounding; Chebyshev bounds; geometric sampling; modular-rank certificates; exact clock monotonicity; genuine KdV tau soliton.','source_gaps':['Recovery is not a complete archive; unrecovered dates and topics are not evidence that mathematics did not occur.','September22–28 returned no dated mathematical passage in the gap-window sweep.','The original Bash scale, all rounding choices, full witness grid and precise Delta statistic were not recovered together; reported micro witnesses are retained as claims and not certified. Newly specified quantizers are labeled as new models.','The11a1 repair passage was truncated after proposed special-value computations; no historical BSD rank or analytic special value is accepted as demonstrated.','No completed proof is inferred from Lean stubs, admitted statements, True theorems, emitted JSON or a runtime VERIFIED message. Formal-gate/axiom-census discussion did not return an additional mathematical model to reconstruct.','Suggested Shimura, endoscopic, motive and full Langlands constructions were not returned with definitions; the finite arithmetic and representation calculations do not claim to construct them.','No verbatim complete original user mathematical prompt was returned; original_question is null throughout.'],'checks':'21 portable stdlib checks pass. Exact arithmetic and finite certificates are distinguished from bounded numerical samples; general theorem claims rely on the written proofs and explicit classical inputs.'}
